from base_sensor import BaseVirtualSensor

class LM83_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x00,  # TEMP_LOCAL
            0x01: 0x00,  # TEMP_D2
            0x02: 0x00,  # SR1
            0x03: 0x00,  # CONFIG
            0x05: 0x7F,  # LHS
            0x07: 0x7F,  # D2RHS
            0x30: 0x00,  # TEMP_D1
            0x31: 0x00,  # TEMP_D3
            0x35: 0x00,  # SR2
            0x38: 0x7F,  # D1RHS
            0x3A: 0x7F,  # D3RHS
            0x42: 0x7F,  # TCS
            0xFE: 0x01,  # MID
            0xFF: 0x00,  # STEP_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            return 0
        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs or self.regs[addr] & 0xFF00 != 0:
            return
        if nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data & 0x00FF

